"""
agent.py  --  MODE DIFICIL
Agent de control per al repte de la bateria de UPC Sostenible. Datathon 2026.

Bateria de 6.000 kWh i +-1.500 kW, solar x12 i nomes 3 hores de mercat conegudes.

Estrategia (control predictiu amb programacio lineal, horitzo mobil):
  1. PREVEURE el mercat: preu i CO2 de les properes 24 h. Les 3 primeres son
     reals (obs); la resta surt del perfil tipic del mes, ajustat al nivell d'avui.
  2. PREVEURE el consum net (consum - solar) de les properes 24 h, a partir de
     l'ultima hora mesurada i dels perfils tipics del mes.
  3. PLANIFICAR AMB INCERTESA: la previsio de consum net mai es exacta, aixi que
     per a cada hora considerem 5 escenaris igual de probables (previsio + error
     tipic d'aquella hora). Un programa lineal tria quan carregar i descarregar
     per minimitzar el pes MITJA (70% CO2, 30% cost) de l'electricitat comprada.
  4. APLICAR nomes la primera hora, amb retall de seguretat (0 infraccions).

Les taules de perfils calculades amb data/train.
"""

import numpy as np
from scipy.optimize import linprog


class BatteryAgent:
    def __init__(self):
        """Inicialitzacio de l'agent (s'executa una sola vegada)."""
        self.rendiment_eta = 0.9 ** 0.5      
        self.hores_pla = 24                 

        # Pesos de la puntuacio oficial i escales de referencia
        self.pes_co2 = 0.7
        self.pes_preu = 0.3
        self.preu_ref = 0.138
        self.co2_ref = 0.6045 * self.preu_ref

        # Parametres de les previsions 
        self.oblit_mercat = 0.97     
        self.oblit_consum = 0.90     
        self.oblit_sol = 0.85        
        self.claredat_tipica = 0.75   

        # Taules de perfils tipics: 
        self.t_preu = np.array(TAULES["preu"])
        self.t_co2 = np.array(TAULES["co2"])
        self.t_consum = np.array(TAULES["load"])
        self.t_sol_clar = np.array(TAULES["pv_env"])  

        # Errors tipics de la previsio de consum net: 
        self.t_errors = np.array(TAULES["errors"])
        self.n_escenaris = self.t_errors.shape[2]

        # Memoria entre hores
        self.claredat = None          
        self.ts_anterior = None
        self.matrius = {}

    def matriu_restriccions(self, n):
        """Restriccions d'un pla de n hores amb S escenaris.
        Variables: c (carrega), d (descarrega) i g[escenari] (compra a la xarxa).
        1) Capacitat: soc + eta*(c_0+...+c_k) - (d_0+...+d_k)/eta entre 0 i la capacitat.
        2) Balanc, per a cada escenari s:  g_{s,t} >= consum_net_{s,t} + c_t - d_t
           (i g >= 0: l'excedent no compta)."""
        if n not in self.matrius:
            S = self.n_escenaris
            acumulat = np.tril(np.ones((n, n)))
            identitat = np.eye(n)
            eta = self.rendiment_eta
            soc = np.hstack([eta * acumulat, -acumulat / eta, np.zeros((n, n * S))])
            balanc = np.hstack([np.tile(identitat, (S, 1)), -np.tile(identitat, (S, 1)), -np.eye(n * S)])
            self.matrius[n] = np.vstack([soc, -soc, balanc])
        return self.matrius[n]

    def previsio_mercat(self, obs, mes, hores, cap_setmana):
        """Pes w de cada hora del pla (com de dolent es comprar 1 kWh a la xarxa)."""
        n = len(hores)
        preus_reals = np.asarray(obs.get("preus_properes_24h") or [obs["preu_actual"]], dtype=float)[:n]
        co2_reals = np.asarray(obs.get("co2_properes_24h") or [obs["co2_actual"]], dtype=float)[:n]
        k_reals = min(len(preus_reals), len(co2_reals))

        preu_tipic = np.array([self.t_preu[mes, cap_setmana[k], hores[k]] for k in range(n)])
        co2_tipic = np.array([self.t_co2[mes, cap_setmana[k], hores[k]] for k in range(n)])

        # Nivell d'avui respecte al tipic 
        nivell_preu = preus_reals[:k_reals].mean() / max(preu_tipic[:k_reals].mean(), 1e-6)
        nivell_co2 = co2_reals[:k_reals].mean() / max(co2_tipic[:k_reals].mean(), 1e-6)
        nivell_preu = min(max(nivell_preu, 0.3), 3.0)
        nivell_co2 = min(max(nivell_co2, 0.3), 3.0)

        # Com mes lluny, menys ens refiem del nivell d'avui
        oblit = self.oblit_mercat ** np.arange(n)
        preus = preu_tipic * (1.0 + (nivell_preu - 1.0) * oblit)
        co2 = co2_tipic * (1.0 + (nivell_co2 - 1.0) * oblit)

        # Les hores que el mercat ja ha publicat son exactes
        preus[:k_reals] = preus_reals[:k_reals]
        co2[:k_reals] = co2_reals[:k_reals]
        return self.pes_co2 * co2 / self.co2_ref + self.pes_preu * preus / self.preu_ref

    def previsio_consum_net(self, obs, mes, hora, dia, hores, cap_setmana):
        """Consum net previst (kW) = consum del campus - solar. Negatiu = sobra solar."""
        n = len(hores)
        dades = obs.get("noves_dades_5min") or {}
        if "ultim_consum_kw" not in dades:
            return np.full(n, 1e6)
        ultim_consum = float(dades["ultim_consum_kw"])
        ultima_solar = float(dades.get("ultima_solar_kw", 0.0))

        # L'ultima mesura correspon a l'hora anterior
        hora_ant = (hora - 1) % 24
        dia_ant = dia if hora > 0 else (dia - 1) % 7
        cap_ant = int(dia_ant >= 5)

        # Consum: perfil tipic escalat pel nivell de l'ultima hora
        nivell = ultim_consum / max(self.t_consum[mes, cap_ant, hora_ant], 1.0)
        nivell = min(max(nivell, 0.2), 3.0)
        tipic = np.array([self.t_consum[mes, cap_setmana[k], hores[k]] for k in range(n)])
        consum = tipic * (1.0 + (nivell - 1.0) * self.oblit_consum ** np.arange(n))

        # Solar: corba de dia clar multiplicada per la claredat observada
        sol_clar = self.t_sol_clar[mes]
        if sol_clar[hora_ant] > 30.0:                    # nomes amb sol suficient
            self.claredat = min(ultima_solar / sol_clar[hora_ant], 1.5)
        claredat = self.claredat if self.claredat is not None else self.claredat_tipica
        factor = self.claredat_tipica + (claredat - self.claredat_tipica) * self.oblit_sol ** np.arange(n)
        solar = np.array([sol_clar[hores[k]] for k in range(n)]) * factor

        return consum - solar

    def act(self, obs: dict) -> float:
        """Consigna de potencia (kW): > 0 carrega, < 0 descarrega, 0 repos."""
        capacitat = float(obs.get("cap_max_kwh", 6000.0))
        potencia_max = float(obs.get("power_max_kw", 1500.0))
        soc_kwh = float(obs["soc_kwh"])
        eta = self.rendiment_eta

        consigna = 0.0
        try:
            ts = obs["timestamp"]
            hora = int(obs["hour"])
            dia = int(obs["day_of_week"])
            mes = int(ts.month) - 1

            # Salt entre setmanes de test: oblidem la nuvolositat antiga
            if self.ts_anterior is not None and (ts - self.ts_anterior).total_seconds() > 2 * 3600 + 1:
                self.claredat = None
            self.ts_anterior = ts

            n = self.hores_pla
            hores = [(hora + k) % 24 for k in range(n)]
            cap_setmana = [int(((dia + (hora + k) // 24) % 7) >= 5) for k in range(n)]

            # 1 i 2. Previsions
            w = self.previsio_mercat(obs, mes, hores, cap_setmana)
            consum_net = self.previsio_consum_net(obs, mes, hora, dia, hores, cap_setmana)

            # 3. Escenaris: previsio + error tipic segons antelacio i hora del dia
            S = self.n_escenaris
            errors = np.array([self.t_errors[k, hores[k]] for k in range(n)])      # [n][S]
            escenaris = consum_net[:, None] + errors

            #    Programa lineal: minimitzar la mitjana sobre escenaris de sum_t w_t * g_{s,t}
            cost = np.concatenate([np.full(2 * n, 1e-6), np.tile(w / S, S)])
            limits = np.concatenate([np.full(n, capacitat - soc_kwh),
                                     np.full(n, soc_kwh),
                                     -escenaris.T.ravel()])
            rangs = [(0.0, potencia_max)] * (2 * n) + [(0.0, None)] * (n * S)
            sol = linprog(cost, A_ub=self.matriu_restriccions(n), b_ub=limits, bounds=rangs, method="highs")
            if sol.status == 0:
                consigna = float(sol.x[0] - sol.x[n])    
        except Exception:
            consigna = 0.0                            

        max_carrega = max(0.0, min(potencia_max, (capacitat - soc_kwh) / eta - 1e-4))
        max_descarrega = max(0.0, min(potencia_max, soc_kwh * eta - 1e-4))
        return float(max(-max_descarrega, min(max_carrega, consigna))) + 0.0


